#!/usr/bin/env python3
"""Cinematic source-derived homepage; source images retain documented approval states."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[2]
lineup=json.loads((R/'canon/characters/APPROVED_LINEUP_2026_10_18.json').read_text())
manifest=json.loads((R/'docs/visual/command-center.json').read_text())
refs=[x for x in lineup['individuals']]
assert len(refs)==12 and all((R/x['crop']).is_file() for x in refs)
hero='../../'+lineup['stored_repository_path']
portraits=''.join('<a class="portrait" href="characters.html" aria-label="Character reference: '+html.escape(x['display_title'],quote=True)+'"><img loading="lazy" src="../../'+html.escape(x['crop'],quote=True)+'" alt="'+html.escape(x['display_title'],quote=True)+'"><span>'+html.escape(x['display_title'])+'</span></a>' for x in refs)
modules=[('The Commonwealth Atlas','atlas.html','Explore the canonical locations and journeys'),('Historical Chronicle','history.html','Follow recorded events and consequences'),('The Story Engine','story-engine.html','Trace how verified league events shape fiction'),('Publication Theatre','publications.html','Browse Memo and Novel release identities'),('Evidence Constellation','evidence.html','Inspect relationships with explicit provenance'),('Systems Observatory','systems.html','See the engineering beneath the mythology'),('Release Intelligence','release.html','Audit the current evidence state'),('The Twelve','characters.html','Meet the canonical character references')]
cards=''.join('<a class="feature" href="'+link+'"><span class="feature-num">'+str(i+1).zfill(2)+'</span><h3>'+title+'</h3><p>'+desc+'</p><span class="discover">ENTER CHAPTER ↗</span></a>' for i,(title,link,desc) in enumerate(modules))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SCHEMIN’ ’26 — Enter the Commonwealth</title>
<meta name="description" content="Explore the living Commonwealth universe, its twelve characters, illustrated histories and intelligence systems.">
<style>
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600;800&family=DM+Sans:wght@400;500;600&display=swap');
:root{color-scheme:dark;--ink:#ede5d4;--muted:#b6ab97;--gold:#c7a16a;--night:#080b10;--line:#74624866}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--night);color:var(--ink);font:15px/1.6 'DM Sans',sans-serif}a{color:inherit;text-decoration:none}a:focus-visible{outline:3px solid #f1c67e;outline-offset:4px}img{max-width:100%}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;display:flex;align-items:center;justify-content:space-between;padding:22px clamp(20px,5vw,84px);border-bottom:1px solid #ffffff2d;background:#080b10a0;backdrop-filter:blur(10px)}.brand{font:600 20px 'Cinzel',Georgia,serif;letter-spacing:.13em}.topbar nav{display:flex;gap:22px;font-size:11px;letter-spacing:.14em;text-transform:uppercase}.topbar nav a:hover{color:var(--gold)}.hero{min-height:100svh;position:relative;display:flex;align-items:end;overflow:hidden;background:#100e12}.hero-art{position:absolute;inset:0;background-image:linear-gradient(90deg,#090b11 0%,#090b11e9 25%,#090b1199 57%,#090b1166 100%),linear-gradient(0deg,#080b10 0%,transparent 50%),url("'''+hero+'''");background-repeat:no-repeat;background-position:center,right center,right center;background-size:cover,cover,auto 94%;filter:saturate(.86)}.hero:after{content:'';position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 72% 35%,transparent 15%,#080b10a6 80%)}.hero-copy{position:relative;z-index:2;padding:190px clamp(20px,8vw,130px) 90px;max-width:1050px}.eyebrow{letter-spacing:.32em;color:var(--gold);font-size:12px;text-transform:uppercase}.hero h1{font:600 clamp(48px,8vw,118px)/.98 'Cinzel',Georgia,serif;letter-spacing:-.045em;margin:24px 0 20px;text-shadow:0 8px 30px #000}.hero h1 em{font-weight:400;font-style:normal;color:var(--gold)}.hero p{font:clamp(17px,2vw,23px)/1.55 Georgia,serif;max-width:610px;color:#e1d6c6}.cta{display:inline-flex;margin-top:26px;border:1px solid var(--gold);padding:15px 26px;font-size:12px;letter-spacing:.22em;background:#3f302099;transition:background .2s}.cta:hover{background:#8a6338}.hero-note{margin-top:32px;max-width:550px;font-size:11px;color:#bdb4a7;letter-spacing:.04em}.section{padding:95px clamp(20px,7vw,110px)}.section-label{font-size:12px;color:var(--gold);letter-spacing:.25em;text-transform:uppercase}.section h2{font:600 clamp(32px,5vw,65px)/1.15 'Cinzel',Georgia,serif;margin:16px 0 26px}.intro{background:radial-gradient(circle at 8% 0%,#30261c,#090c10 50%);border-top:1px solid var(--line)}.intro p{font:20px/1.7 Georgia,serif;max-width:830px;color:#c7bdac}.portraits{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px;margin-top:34px}.portrait{border:1px solid var(--line);background:#17191d;overflow:hidden;position:relative;min-height:200px}.portrait img{height:230px;width:100%;object-fit:cover;object-position:center top;display:block;transition:transform .5s}.portrait:hover img{transform:scale(1.06)}.portrait span{display:block;background:#11151c;padding:12px 10px;font:11px 'Cinzel',serif;min-height:55px}.editorial{background:#111419;border-top:1px solid var(--line)}.chapter-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line)}.feature{min-height:260px;padding:28px;background:#12181e;display:flex;flex-direction:column;transition:background .25s}.feature:hover{background:#29251e}.feature-num{font:14px Georgia,serif;color:var(--gold)}.feature h3{font:24px/1.2 'Cinzel',serif;margin:38px 0 10px}.feature p{color:var(--muted);margin:0}.discover{font-size:10px;color:var(--gold);letter-spacing:.13em;margin-top:auto;padding-top:28px}.colophon{border-top:1px solid var(--line);background:#090c10;color:var(--muted);padding:35px 7%;font-size:12px}.colophon a{color:var(--gold)}@media(max-width:1000px){.chapter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.portraits{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:650px){.topbar{position:absolute;display:block;padding:16px 20px}.topbar nav{overflow-x:auto;white-space:nowrap;gap:15px;margin-top:12px}.hero-art{background-position:center,right center,70% 25%;background-size:cover,cover,auto 60%;opacity:.8}.hero-copy{padding:225px 24px 60px}.hero h1{font-size:clamp(41px,11vw,65px)}.portraits{grid-template-columns:repeat(2,minmax(0,1fr))}.portrait img{height:180px}.chapter-grid{grid-template-columns:1fr}.section{padding:65px 23px}.feature{min-height:210px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.portrait img,.feature,.cta{transition:none}}
</style></head><body><header class="topbar"><a class="brand" href="index.html">SCHEMIN’ ’26</a><nav aria-label="Primary"><a href="#world">The World</a><a href="#twelve">The Twelve</a><a href="#chapters">Explore</a><a href="atlas.html">Atlas</a></nav></header>
<main><section class="hero"><div class="hero-art" role="img" aria-label="The Commissioner-approved twelve-character visual lineup"></div><div class="hero-copy"><div class="eyebrow">The Commonwealth · A living fantasy universe</div><h1>EVERY WEEK<br><em>MAKES HISTORY.</em></h1><p>Twelve rulers. One persistent world. A real fantasy league whose victories, betrayals and rivalries become illustrated legend.</p><a href="#world" class="cta">ENTER THE COMMONWEALTH ↓</a><div class="hero-note">Hero artwork: October 18 Commissioner-approved lineup presentation. Character rendering and independent QA approvals remain separate.</div></div></section>
<section class="section intro" id="world"><div class="section-label">I. The World Remembers</div><h2>More than a game.<br>A world in motion.</h2><p>Every verified league event enters a shared fictional reality. Its characters remember, its landscapes carry consequences, and its stories continue through illustrated Memos, novels and cinematic production.</p><a class="cta" href="story-engine.html">EXPLORE THE STORY ENGINE ↗</a></section>
<section class="section" id="twelve"><div class="section-label">II. The Inhabitants</div><h2>Meet the Twelve.</h2><p>The current Commissioner-approved comparative visual lineup. These are canonical presentation references, not an unconditional approval of generated imagery.</p><div class="portraits">'''+portraits+'''</div></section>
<section class="section editorial" id="chapters"><div class="section-label">III. Enter the Archives</div><h2>Explore the Commonwealth.</h2><div class="chapter-grid">'''+cards+'''</div></section></main>
<footer class="colophon">SCHEMIN’ ’26 — Internal review experience · All facts and artworks remain governed by canonical approvals. <a href="command-center.json">Source register</a> · <a href="evidence.html">Evidence graph</a></footer></body></html>'''
(R/'docs/visual/index.html').write_text(page)
print('CINEMATIC_HOME',len(page),'bytes, portraits',len(refs),'chapters',len(modules),'source modules',len(manifest['modules']))
